#!/usr/bin/env python3
'''Deterministic CPU-only checks for K-MODEL-014 mechanisms.'''

import math
from fractions import Fraction


def shape_out(n, k, p, s, d):
    return (n + 2 * p - d * (k - 1) - 1) // s + 1


def make_input(B, C, H, W, seed):
    X = []
    for b in range(B):
        xb = []
        for c in range(C):
            xc = []
            for y in range(H):
                row = []
                for x in range(W):
                    row.append(((b * 7 + c * 5 + y * 3 + x * 11 + seed) % 9) - 4)
                xc.append(row)
            xb.append(xc)
        X.append(xb)
    return X


def make_weight(Cout, Cin_local, Kh, Kw, seed):
    W = []
    for co in range(Cout):
        wco = []
        for ci in range(Cin_local):
            wci = []
            for ky in range(Kh):
                row = []
                for kx in range(Kw):
                    row.append(((co * 3 + ci * 7 + ky * 5 + kx * 2 + seed) % 7) - 3)
                wci.append(row)
            wco.append(wci)
        W.append(wco)
    return W


def conv_direct(X, W, bias, stride, pad, dil, G):
    B = len(X)
    Cin = len(X[0])
    H = len(X[0][0])
    Win = len(X[0][0][0])
    Cout = len(W)
    Kh = len(W[0][0])
    Kw = len(W[0][0][0])
    if Cin % G != 0 or Cout % G != 0:
        raise ValueError('bad groups')
    Hout = shape_out(H, Kh, pad[0], stride[0], dil[0])
    Wout = shape_out(Win, Kw, pad[1], stride[1], dil[1])
    if Hout <= 0 or Wout <= 0:
        return []
    cin_g = Cin // G
    cout_g = Cout // G
    Y = []
    for b in range(B):
        yb = []
        for co in range(Cout):
            g = co // cout_g
            yc = []
            for oy in range(Hout):
                row = []
                for ox in range(Wout):
                    acc = 0
                    for cl in range(cin_g):
                        ci = g * cin_g + cl
                        for ky in range(Kh):
                            iy = oy * stride[0] - pad[0] + ky * dil[0]
                            if iy < 0 or iy >= H:
                                continue
                            for kx in range(Kw):
                                ix = ox * stride[1] - pad[1] + kx * dil[1]
                                if ix < 0 or ix >= Win:
                                    continue
                                acc += X[b][ci][iy][ix] * W[co][cl][ky][kx]
                    if bias is not None:
                        acc += bias[co]
                    row.append(acc)
                yc.append(row)
            yb.append(yc)
        Y.append(yb)
    return Y


def conv_im2col(X, W, bias, stride, pad, dil, G):
    B = len(X)
    Cin = len(X[0])
    H = len(X[0][0])
    Win = len(X[0][0][0])
    Cout = len(W)
    Kh = len(W[0][0])
    Kw = len(W[0][0][0])
    if Cin % G != 0 or Cout % G != 0:
        raise ValueError('bad groups')
    Hout = shape_out(H, Kh, pad[0], stride[0], dil[0])
    Wout = shape_out(Win, Kw, pad[1], stride[1], dil[1])
    if Hout <= 0 or Wout <= 0:
        return []
    cin_g = Cin // G
    cout_g = Cout // G
    Y = []
    for b in range(B):
        yb = []
        for co in range(Cout):
            yc = []
            for oy in range(Hout):
                yc.append([0 for _ in range(Wout)])
            yb.append(yc)
        Y.append(yb)
    for b in range(B):
        for g in range(G):
            A = []
            for oy in range(Hout):
                for ox in range(Wout):
                    row = []
                    for cl in range(cin_g):
                        ci = g * cin_g + cl
                        for ky in range(Kh):
                            iy = oy * stride[0] - pad[0] + ky * dil[0]
                            for kx in range(Kw):
                                ix = ox * stride[1] - pad[1] + kx * dil[1]
                                if 0 <= iy < H and 0 <= ix < Win:
                                    row.append(X[b][ci][iy][ix])
                                else:
                                    row.append(0)
                    A.append(row)
            for co_local in range(cout_g):
                co = g * cout_g + co_local
                wrow = []
                for cl in range(cin_g):
                    for ky in range(Kh):
                        for kx in range(Kw):
                            wrow.append(W[co][cl][ky][kx])
                for idx in range(Hout * Wout):
                    oy = idx // Wout
                    ox = idx % Wout
                    acc = 0
                    for k in range(len(wrow)):
                        acc += A[idx][k] * wrow[k]
                    if bias is not None:
                        acc += bias[co]
                    Y[b][co][oy][ox] = acc
    return Y


def test_conv():
    X1 = make_input(1, 4, 5, 6, 1)
    W1 = make_weight(4, 2, 3, 3, 2)
    b1 = [1, -2, 3, 0]
    Y1a = conv_direct(X1, W1, b1, (1, 1), (1, 1), (1, 1), 2)
    Y1b = conv_im2col(X1, W1, b1, (1, 1), (1, 1), (1, 1), 2)
    expect('conv_grouped_direct_vs_im2col', Y1a == Y1b, 'shape=' + str(len(Y1a)) + 'x' + str(len(Y1a[0])) + 'x' + str(len(Y1a[0][0])))

    X2 = make_input(1, 3, 4, 5, 2)
    W2 = make_weight(6, 1, 2, 3, 3)
    b2 = [0, 1, -1, 2, 0, -2]
    Y2a = conv_direct(X2, W2, b2, (2, 2), (1, 1), (2, 2), 3)
    Y2b = conv_im2col(X2, W2, b2, (2, 2), (1, 1), (2, 2), 3)
    expect('conv_dilation_direct_vs_im2col', Y2a == Y2b, 'dilation=2 stride=2')

    wrong = conv_direct(X2, W2, b2, (2, 2), (1, 1), (1, 1), 3)
    expect('negative_conv_ignores_dilation', wrong != Y2a, 'wrong path differs from reference')

    X3 = make_input(1, 2, 1, 1, 0)
    W3 = make_weight(2, 2, 2, 2, 1)
    Y3a = conv_direct(X3, W3, None, (1, 1), (0, 0), (1, 1), 1)
    Y3b = conv_im2col(X3, W3, None, (1, 1), (0, 0), (1, 1), 1)
    expect('conv_empty_output', Y3a == [] and Y3b == [], 'kernel larger than input without pad')


def bn_ref(x, w, b, gamma, beta, mean, den):
    return gamma * (w * x + b - mean) / den + beta


def fold_bn(w, b, gamma, beta, mean, den):
    a = gamma / den
    return a * w, a * (b - mean) + beta


def test_bn_and_residual():
    gamma = Fraction(4, 1)
    beta = Fraction(1, 2)
    mean = Fraction(1, 1)
    den = Fraction(2, 1)
    w = Fraction(2, 1)
    b = Fraction(1, 4)
    wf, bf = fold_bn(w, b, gamma, beta, mean, den)
    for x in [Fraction(-3, 1), Fraction(0, 1), Fraction(2, 1), Fraction(7, 3)]:
        u = bn_ref(x, w, b, gamma, beta, mean, den)
        v = wf * x + bf
        if u != v:
            raise AssertionError('folded BN mismatch at ' + str(x))
    expect('bn_fold_exact', True, 'four rational inputs')

    a = gamma / den
    wrong_bias = a * b + beta
    wrong = wf * Fraction(2, 1) + wrong_bias
    right = bn_ref(Fraction(2, 1), w, b, gamma, beta, mean, den)
    expect('negative_bn_missing_mean', wrong != right, 'wrong fold misses mean subtraction')

    x = [Fraction(1, 1), Fraction(2, 1), Fraction(3, 1)]
    def f(v):
        return [z + 1 for z in v]
    correct = [x[i] + f(x)[i] for i in range(len(x))]
    overwritten = f(x)
    bug = [overwritten[i] + overwritten[i] for i in range(len(x))]
    expect('negative_residual_inplace_overwrite', correct != bug, 'correct=' + str(correct) + ' bug=' + str(bug))


def letterbox(W, H, Wt, Ht):
    s = min(Fraction(Wt, W), Fraction(Ht, H))
    px = (Fraction(Wt, 1) - Fraction(W, 1) * s) / 2
    py = (Fraction(Ht, 1) - Fraction(H, 1) * s) / 2
    return s, px, py


def map_point(pt, s, px, py):
    return (px + s * pt[0], py + s * pt[1])


def inv_point(pt, s, px, py):
    return ((pt[0] - px) / s, (pt[1] - py) / s)


def test_coordinates():
    s, px, py = letterbox(6, 4, 8, 8)
    p = (Fraction(3, 1), Fraction(2, 1))
    q = map_point(p, s, px, py)
    r = inv_point(q, s, px, py)
    expect('letterbox_center_maps_to_center', q == (Fraction(4, 1), Fraction(4, 1)), 'mapped=' + str(q))
    expect('letterbox_roundtrip', r == p, 'inverse=' + str(r))

    wrong = inv_point(q, s, Fraction(0, 1), Fraction(0, 1))
    expect('negative_letterbox_missing_pad', wrong != p, 'wrong inverse=' + str(wrong))

    box = (Fraction(1, 1), Fraction(1, 1), Fraction(5, 1), Fraction(3, 1))
    tb = (map_point((box[0], box[1]), s, px, py)[0], map_point((box[0], box[1]), s, px, py)[1], map_point((box[2], box[3]), s, px, py)[0], map_point((box[2], box[3]), s, px, py)[1])
    rb = (inv_point((tb[0], tb[1]), s, px, py)[0], inv_point((tb[0], tb[1]), s, px, py)[1], inv_point((tb[2], tb[3]), s, px, py)[0], inv_point((tb[2], tb[3]), s, px, py)[1])
    expect('box_roundtrip', rb == box, 'target=' + str(tb))


def area(b):
    w = b[2] - b[0]
    h = b[3] - b[1]
    if w <= 0 or h <= 0:
        return Fraction(0, 1)
    return w * h


def inter(a, b):
    x1 = max(a[0], b[0])
    y1 = max(a[1], b[1])
    x2 = min(a[2], b[2])
    y2 = min(a[3], b[3])
    if x2 <= x1 or y2 <= y1:
        return Fraction(0, 1)
    return (x2 - x1) * (y2 - y1)


def iou(a, b):
    u = area(a) + area(b) - inter(a, b)
    if u <= 0:
        return Fraction(0, 1)
    return inter(a, b) / u


def clip_box(b, W, H):
    x1 = max(Fraction(0, 1), min(b[0], Fraction(W, 1)))
    y1 = max(Fraction(0, 1), min(b[1], Fraction(H, 1)))
    x2 = max(Fraction(0, 1), min(b[2], Fraction(W, 1)))
    y2 = max(Fraction(0, 1), min(b[3], Fraction(H, 1)))
    if x2 <= x1 or y2 <= y1:
        return None
    return (x1, y1, x2, y2)


def nms(boxes, scores, thr, classes=None, class_aware=False, strict=True):
    n = len(boxes)
    if n == 0:
        return []
    order = sorted(range(n), key=lambda i: (-scores[i], i))
    suppressed = [False for _ in range(n)]
    keep = []
    for pos, i in enumerate(order):
        if suppressed[i]:
            continue
        keep.append(i)
        for j in order[pos + 1:]:
            if suppressed[j]:
                continue
            if class_aware and classes is not None and classes[i] != classes[j]:
                continue
            val = iou(boxes[i], boxes[j])
            if strict:
                hit = val > thr
            else:
                hit = val >= thr
            if hit:
                suppressed[j] = True
    return keep


def test_nms():
    a = (Fraction(0, 1), Fraction(0, 1), Fraction(2, 1), Fraction(2, 1))
    b = (Fraction(1, 1), Fraction(0, 1), Fraction(3, 1), Fraction(2, 1))
    boxes = [a, b]
    scores = [Fraction(9, 10), Fraction(8, 10)]
    thr = Fraction(1, 3)
    keep_gt = nms(boxes, scores, thr, strict=True)
    keep_ge = nms(boxes, scores, thr, strict=False)
    expect('nms_threshold_iou', iou(a, b) == thr, 'iou=1/3')
    expect('nms_strict_keeps_boundary', keep_gt == [0, 1], 'keep=' + str(keep_gt))
    expect('negative_nms_ge_suppresses_boundary', keep_ge != keep_gt, 'ge_keep=' + str(keep_ge))

    raw = [(Fraction(-2, 1), Fraction(0, 1), Fraction(2, 1), Fraction(2, 1)), (Fraction(0, 1), Fraction(0, 1), Fraction(4, 1), Fraction(2, 1))]
    raw_scores = [Fraction(9, 10), Fraction(8, 10)]
    raw_keep = nms(raw, raw_scores, Fraction(1, 2), strict=True)
    clipped = []
    for box in raw:
        cb = clip_box(box, 3, 3)
        if cb is not None:
            clipped.append(cb)
    clip_keep = nms(clipped, raw_scores, Fraction(1, 2), strict=True)
    expect('nms_clip_order_changes_result', raw_keep == [0, 1] and clip_keep == [0], 'raw=' + str(raw_keep) + ' clipped=' + str(clip_keep))

    same = [(Fraction(0, 1), Fraction(0, 1), Fraction(2, 1), Fraction(2, 1)), (Fraction(0, 1), Fraction(0, 1), Fraction(2, 1), Fraction(2, 1))]
    ss = [Fraction(1, 1), Fraction(1, 1)]
    k_ca = nms(same, ss, Fraction(1, 2), classes=[0, 1], class_aware=True)
    k_cg = nms(same, ss, Fraction(1, 2), classes=[0, 1], class_aware=False)
    expect('nms_class_awareness', k_ca == [0, 1] and k_cg == [0], 'aware=' + str(k_ca) + ' agnostic=' + str(k_cg))
    expect('nms_empty', nms([], [], Fraction(1, 2)) == [], 'empty returns empty')


def expect(name, cond, detail):
    if not cond:
        raise AssertionError(name + ': ' + detail)
    print('OBS ' + name + ' ' + detail)


def main():
    test_conv()
    test_bn_and_residual()
    test_coordinates()
    test_nms()
    print('SCOPED_OBSERVATIONS_ONLY CPU binary/rational model; no GPU measurement')


if __name__ == '__main__':
    main()
